def dedupe(items):
    seen = []
    result = []
    for item in items:
        # Convert to a hashable representation for comparison
        try:
            # Try to use the item directly if it's hashable
            if item not in seen:
                seen.append(item)
                result.append(item)
        except TypeError:
            # If item is not hashable, check by equality
            found = False
            for seen_item in seen:
                if seen_item == item:
                    found = True
                    break
            if not found:
                seen.append(item)
                result.append(item)
    return result
